theme.css:
/* theme: Final Stretch | An election-eve page built like a campaign mailer — heavy, urgent, and stamped with the countdown's closing hours. */
/* layout: hero=poster; political-news=banner/grid-2; financial-news=stat/stack; entertainment-news=tile/grid-3; music-releases=lede/masonry; stock-analysis=numbered/grid-2; outlook=outline/stack */

.diary-page {
  --paper: #fcfbf7;
  --paper-alt: #f0ede4;
  --ink: #1a1612;
  --ink-soft: #3a332b;
  --muted: #6b6256;
  --accent: #b03a2e;
  --accent-ink: #fff8f0;
  --rule: #d8d0c0;
  --font-display: var(--ff-archivo-black), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background:
    repeating-linear-gradient(
      -45deg,
      var(--accent) 0 14px,
      var(--accent-ink) 14px 16px
    );
  border-bottom: 4px solid var(--ink);
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  max-width: 76rem;
  margin-inline: auto;
  padding: 2.5rem 1.25rem 3.5rem;
}

.diary-page[data-hero="poster"] .diary-crumbs a {
  color: var(--accent-ink);
  font-weight: 700;
}

.diary-page[data-hero="poster"] .diary-kicker {
  color: var(--accent-ink);
  letter-spacing: 0.22em;
  text-shadow: 2px 2px 0 rgba(0,0,0,0.25);
}

.diary-page[data-hero="poster"] .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.8rem, 8vw, 6rem);
  line-height: 0.9;
  text-transform: uppercase;
  color: var(--accent-ink);
  max-width: none;
  letter-spacing: 0.01em;
}

.diary-page[data-hero="poster"] .diary-summary {
  margin-top: 1.25rem;
  color: var(--accent-ink);
  font-weight: 500;
  max-width: 44rem;
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  text-shadow: 1px 1px 0 rgba(0,0,0,0.2);
}

.diary-page[data-hero="poster"] .diary-theme-note {
  margin-top: 2rem;
  color: var(--accent-ink);
  font-weight: 500;
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
}

.diary-page .diary-theme-name {
  border-radius: 2px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 0.25rem 0.85rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 2px solid var(--ink);
}

.diary-page .diary-toc-number {
  font-weight: 800;
}

.diary-page .diary-section {
  padding-block: 3.25rem;
}

.diary-page .diary-section-head {
  border-bottom: 0;
  margin-bottom: 2rem;
  padding-bottom: 0.75rem;
  border-bottom: 3px solid var(--ink);
}

.diary-page .diary-section-number {
  font-size: 0.9rem;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  text-transform: uppercase;
  letter-spacing: 0.02em;
  line-height: 1;
}

.diary-page .diary-card--banner .diary-card-inner {
  gap: 0;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 0;
  box-shadow: 6px 6px 0 rgba(26,22,18,0.25);
  background: var(--paper);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  padding: 1rem 1.25rem 0.9rem;
  font-size: 1.2rem;
  letter-spacing: 0.01em;
  border-bottom: 2px solid var(--ink);
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.5rem 1.25rem 1.75rem;
}

.diary-page .diary-card--banner .diary-card-thread {
  margin: 1.25rem 1.25rem 0;
}

.diary-page .diary-card--stat .diary-card-inner {
  padding: 1.25rem;
  border: 2px solid var(--ink);
  border-top: 6px solid var(--accent);
  border-radius: 0;
  box-shadow: 4px 4px 0 rgba(26,22,18,0.15);
  background: var(--paper-alt);
}

.diary-page .diary-card-figure {
  font-size: clamp(2.75rem, 10cqi, 4rem);
  color: var(--accent);
  letter-spacing: 0.01em;
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem;
  box-shadow: inset 4px 0 0 var(--accent);
}

.diary-page .diary-card--tile .diary-card-title {
  font-size: 1.15rem;
  font-family: var(--font-display);
  letter-spacing: 0.01em;
  line-height: 1.15;
}

.diary-page .diary-card--lede .diary-card-inner {
  border: 0;
  padding: 0;
}

.diary-page .diary-card-lede {
  background: var(--accent);
  color: var(--accent-ink);
  padding: 1.25rem;
  border-left: 0;
  font-family: var(--font-body);
  font-size: 1.25rem;
  font-weight: 500;
  border-radius: 0;
  margin-bottom: 0.5rem;
}

.diary-page .diary-card--numbered .diary-card-inner {
  border: 1px solid var(--rule);
  padding: 1.25rem;
  background: var(--paper);
  border-radius: 0;
  box-shadow: 3px 3px 0 rgba(26,22,18,0.1);
  gap: 0.5rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.5rem;
  color: var(--accent);
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.35rem;
  margin-bottom: 0.25rem;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-size: 1.25rem;
}

.diary-page .diary-card--outline .diary-card-inner {
  padding: 1.75rem;
  border: 2px solid var(--ink);
  border-radius: 0;
  background: var(--paper);
  box-shadow: 5px 5px 0 rgba(26,22,18,0.2);
}

.diary-page .diary-card--outline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: 0.01em;
}

.diary-page .diary-card-body {
  font-size: 1.06rem;
  line-height: 1.7;
}

.diary-page .diary-prose {
  font-weight: 400;
}

.diary-page .diary-prose a {
  font-weight: 800;
  border-bottom: 2px solid currentColor;
  padding-bottom: 0.05em;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  padding-left: 1.5rem;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  height: 3px;
  width: 0.75rem;
  top: 0.8em;
}

.diary-page .diary-card-thread {
  border: 2px solid var(--accent);
  border-radius: 0;
  font-weight: 700;
  padding: 0.15rem 0.7rem 0.1rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
}

.diary-page .diary-markets {
  background: var(--paper-alt);
  border: 2px solid var(--ink);
  border-radius: 0;
}

.diary-page .diary-spark {
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-footer {
  border-top: 3px solid var(--ink);
  background: var(--paper-alt);
  padding-block: 2.5rem 3.5rem;
}

.diary-page .diary-footer a {
  font-weight: 800;
}

.diary-page .diary-stories--stack {
  max-width: 46rem;
}

.diary-page .diary-stories--grid-3 {
  gap: 1.5rem;
}

.diary-page .diary-stories--masonry .diary-card {
  margin-bottom: 1.5rem;
}

@media (min-width: 1024px) {
  .diary-page[data-hero="poster"] .diary-hero-inner {
    padding-top: 3rem;
    padding-bottom: 4.5rem;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
